# Settle the selected claims together, in list order; responds with how many settled and refused, and the claims.
settle:
  class: net.officefloor.hq.app.claim.BulkSettleClaims
  govern: [ transaction ]
# Change a claim's status: {change} is open, settle, void, approve, reject, delete or restore (a reject with {"reason"} in the body). Responds with the sheet's claims.
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimStatus
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaims
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Settles each selected claim in list order (people by their list positions, newest claim first within a
 * person) by the rules of settling one claim, as the signed-in user; one a clerk's settle sends to PENDING counts as
 * settled. It is all or nothing: when any selected claim cannot be settled none is, every one counts refused and
 * nothing is written. Otherwise the bulk settle is the sheet's next batch, each claim it settled carries the batch's
